### 🧪 **Example of Secure Secret Loading (for when needed)**

When this app is extended to use these secrets, ensure they are loaded securely:

```javascript
require('dotenv').config();

// Validate required secrets at startup
const requiredEnvVars = [
  'DATABASE_URL',
  'LOGFIRE_TOKEN' // if using logging
];

for (const envVar of requiredEnvVars) {
  if (!process.env[envVar]) {
    console.error(`Missing required environment variable: ${envVar}`);
    process.exit(1); // Crash at startup rather than run insecurely
  }
}

// Example: Secure logging mask
const logSafeEnv = { ...process.env };
delete logSafeEnv.DATABASE_URL;
console.log('Starting app with env:', Object.keys(logSafeEnv));
```

#### 🛡 **For Production: Use Secrets Manager Instead**
Here's an example with HashiCorp Vault:

```javascript
const vault = require('node-vault')({ endpoint: 'http://127.0.0.1:8200' });

async function loadSecrets() {
  try {
    const { data } = await vault.read('secret/data/myapp');
    return data.data;
  } catch (err) {
    console.error('Failed to fetch secrets from Vault:', err.message);
    process.exit(1);
  }
}

// Later, in app startup
loadSecrets().then(secrets => {
  process.env.DATABASE_URL = secrets.DATABASE_URL;
  // ...other secrets
});
```

