const { Client } = require('@hashicorp/vault-client'); // Example vault client

// Secure environment variable loader with fallback
const loadSecrets = async () => {
  const secrets = {};

  // Try vault first (production)
  try {
    const vaultClient = new Client({
      token: process.env.VAULT_TOKEN,
      address: process.env.VAULT_ADDR
