const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const hpp = require('hpp');
const cors = require('cors');

const app = express();

// Security: Set HTTP headers to protect against common web vulnerabilities
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc: ["'self'"],
            styleSrc: ["'self'"],
            imgSrc: ["'self'"],
            connectSrc: ["'self'"],
            fontSrc: ["'self'"],
            objectSrc: ["'none'"],
            frameAncestors: ["'none'"]
        }
    },
    hidePoweredBy: true,
    noSniff: true,
    ieNoOpen: true,
    frameguard: { action: 'deny' }
}));

// Security: Prevent parameter pollution attacks
app.use(hpp());

// Security: Limit rate to prevent brute force and DoS attacks
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: {
        error: 'Too many requests from this IP, please try again later.'
    },
    standardHeaders: true,
    legacyHeaders: false
});
app.use(limiter);

// Security: Handle CORS properly
app.use(cors({
    origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true
}));

// Security: Add validation middleware
function validateRequest(req, res, next) {
    if (!req.accepts('json')) {
        return res.status(406).json({ error: 'Not acceptable. Only JSON responses are supported.' });
    }
    next();
}

// Middleware to apply validation to all routes
app.use('*', validateRequest);

// Health check endpoint (publicly accessible)
app.get('/health', (req, res) => {
